import { useState } from 'react'
import api from '../services/api'

export default function ElectiveEntryPage() {
  const [entries, setEntries] = useState([
    { id: Date.now(), name: '', credits: '', description: '', error: '' }
  ])
  const [submitError, setSubmitError] = useState('')
  const [loading, setLoading] = useState(false)
  const [success, setSuccess] = useState(false)

  const addEntry = () => {
    setSubmitError('')
    setSuccess(false)
    setEntries([
      ...entries,
      { id: Date.now(), name: '', credits: '', description: '', error: '' }
    ])
  }

  const removeEntry = (id) => {
    if (entries.length === 1) return
    setSubmitError('')
    setSuccess(false)
    setEntries(entries.filter(entry => entry.id !== id))
  }

  const handleUpdate = (id, field, value) => {
    setSubmitError('')
    setSuccess(false)
    setEntries(entries.map(entry => {
      if (entry.id === id) {
        const updated = { ...entry, [field]: value, error: '' }
        
        // Real-time character limit validation
        if (field === 'name' && value.length > 50) {
          updated.error = 'Pavadinimas negali viršyti 50 simbolių'
        } else if (field === 'description' && value.length > 2000) {
          updated.error = 'Aprašymas negali viršyti 2000 simbolių'
        } else if (field === 'credits' && value !== '' && (isNaN(Number(value)) || Number(value) <= 0)) {
          updated.error = 'Kreditai turi būti teigiamas skaičius'
        }
        
        return updated
      }
      return entry
    }))
  }

  const validate = () => {
    let isValid = true
    const newEntries = [...entries]
    const names = new Set()

    // 1. Check for empty list (all names empty)
    const hasContent = entries.some(e => e.name.trim().length > 0)
    if (!hasContent) {
      setSubmitError('Sąrašas negali būti tuščias. Įveskite bent vieno dalyko pavadinimą.')
      return false
    }

    for (let i = 0; i < newEntries.length; i++) {
      const entry = newEntries[i]
      const trimmedName = entry.name.trim().toLowerCase()

      // 2. Name cannot be empty
      if (!entry.name.trim()) {
        newEntries[i] = { ...entry, error: 'Pavadinimas privalomas' }
        isValid = false
        continue
      }

      // 3. Max length (re-check on submit)
      if (entry.name.length > 50) {
        newEntries[i] = { ...entry, error: 'Pavadinimas per ilgas (maks. 50)' }
        isValid = false
        continue
      }

      if (entry.description.length > 2000) {
        newEntries[i] = { ...entry, error: 'Aprašymas per ilgas (maks. 2000)' }
        isValid = false
        continue
      }

      if (entry.credits === '' || entry.credits == null) {
        newEntries[i] = { ...entry, error: 'Kreditai privalomi' }
        isValid = false
        continue
      }

      if (isNaN(Number(entry.credits)) || Number(entry.credits) <= 0) {
        newEntries[i] = { ...entry, error: 'Kreditai turi būti teigiamas skaičius' }
        isValid = false
        continue
      }

      // 4. Duplicate prevention
      if (names.has(trimmedName)) {
        newEntries[i] = { ...entry, error: 'Šis pavadinimas jau naudojamas sąraše' }
        isValid = false
      } else {
        names.add(trimmedName)
      }
    }

    setEntries(newEntries)
    return isValid
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    setSubmitError('')
    setSuccess(false)

    if (!validate()) return

    setLoading(true)
    try {
      await api.post('/elective-courses', { entries })
      setSuccess(true)
      // Clear form after success
      setEntries([{ id: Date.now(), name: '', credits: '', description: '', error: '' }])
    } catch (err) {
      setSubmitError(err.response?.data?.error || 'Nepavyko išsaugoti duomenų. Bandykite dar kartą.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="max-w-2xl pb-12">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 mb-1">Pridėti pasirenkamus dalykus</h1>
          <p className="text-sm text-slate-400">Įveskite informaciją apie jus dominančius dalykus</p>
        </div>
        <button
          onClick={addEntry}
          type="button"
          disabled={loading}
          className="flex items-center gap-2 px-4 py-2 bg-brand-50 text-brand-700 text-sm font-semibold rounded-xl hover:bg-brand-100 transition-colors border border-brand-200 disabled:opacity-50"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
          </svg>
          Pridėti kitą
        </button>
      </div>

      {submitError && (
        <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-xl flex items-center gap-3 text-sm text-red-700 animate-in fade-in slide-in-from-top-2">
          <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m9-.75a9 9 0 11-18 0 9 9 0 0118 0zm-9 3.75h.008v.008H12v-.008z" />
          </svg>
          {submitError}
        </div>
      )}

      {success && (
        <div className="mb-6 p-4 bg-green-50 border border-green-200 rounded-xl flex items-center gap-3 text-sm text-green-700 animate-in fade-in slide-in-from-top-2">
          <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          Dalykai sėkmingai išsaugoti!
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-6">
        {entries.map((entry, index) => (
          <div 
            key={entry.id} 
            className={`relative bg-white p-6 border rounded-2xl shadow-sm transition-all hover:border-slate-300 ${
              entry.error ? 'border-red-300 bg-red-50/10' : 'border-slate-200'
            }`}
          >
            {entries.length > 1 && (
              <button
                onClick={() => removeEntry(entry.id)}
                className="absolute top-4 right-4 p-2 text-slate-400 hover:text-red-500 transition-colors"
                type="button"
                disabled={loading}
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M14.74 9l-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 01-2.244 2.077H8.084a2.25 2.25 0 01-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 00-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 013.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 00-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 00-7.5 0" />
                </svg>
              </button>
            )}
            
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="md:col-span-3 space-y-2">
                <label className="text-sm font-medium text-slate-700 flex justify-between">
                  <span>Dalyko pavadinimas <span className="text-slate-300 ml-1 font-normal">#{index + 1}</span></span>
                  <span className={`text-xs ${entry.name.length > 50 ? 'text-red-500 font-bold' : 'text-slate-400'}`}>
                    {entry.name.length}/50
                  </span>
                </label>
                <input
                  type="text"
                  value={entry.name}
                  onChange={(e) => handleUpdate(entry.id, 'name', e.target.value)}
                  placeholder="Pvz.: Dirbtinis intelektas"
                  disabled={loading}
                  className={`w-full px-4 py-2.5 text-sm border rounded-xl focus:outline-none focus:ring-2 transition-all ${
                    entry.error && !entry.name.trim() || entry.name.length > 50
                      ? 'border-red-300 focus:ring-red-200'
                      : 'border-slate-200 focus:ring-brand-500'
                  }`}
                />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-medium text-slate-700 block">
                  Kreditai
                </label>
                <input
                  type="number"
                  value={entry.credits}
                  onChange={(e) => handleUpdate(entry.id, 'credits', e.target.value)}
                  placeholder="6"
                  disabled={loading}
                  className="w-full px-4 py-2.5 text-sm border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-transparent placeholder:text-slate-400"
                />
              </div>

              <div className="md:col-span-4 space-y-2">
                <label className="text-sm font-medium text-slate-700 flex justify-between">
                  <span>Aprašymas</span>
                  <span className={`text-xs ${entry.description.length > 2000 ? 'text-red-500 font-bold' : 'text-slate-400'}`}>
                    {entry.description.length}/2000
                  </span>
                </label>
                <textarea
                  value={entry.description}
                  onChange={(e) => handleUpdate(entry.id, 'description', e.target.value)}
                  placeholder="Trumpai apibūdinkite dalyko temas, tikslus ar reikalavimus..."
                  rows="3"
                  disabled={loading}
                  className={`w-full px-4 py-2.5 text-sm border rounded-xl focus:outline-none focus:ring-2 transition-all resize-none ${
                    entry.description.length > 2000
                      ? 'border-red-300 focus:ring-red-200'
                      : 'border-slate-200 focus:ring-brand-500'
                  }`}
                ></textarea>
              </div>

              {entry.error && (
                <div className="md:col-span-4 flex items-center gap-2 text-xs font-medium text-red-600">
                  <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m9-.75a9 9 0 11-18 0 9 9 0 0118 0zm-9 3.75h.008v.008H12v-.008z" />
                  </svg>
                  {entry.error}
                </div>
              )}
            </div>
          </div>
        ))}

        <div className="pt-4 flex items-center gap-4">
          <button
            type="submit"
            disabled={loading}
            className="px-8 py-3 bg-brand-600 text-white text-sm font-bold rounded-xl hover:bg-brand-700 transition-all shadow-md hover:shadow-lg flex items-center gap-2 active:scale-95 disabled:opacity-50"
          >
            {loading ? (
              <>
                <svg className="w-4 h-4 animate-spin" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z" />
                </svg>
                Išsaugoma...
              </>
            ) : 'Išsaugoti visus'}
          </button>
          
          <button
            onClick={addEntry}
            type="button"
            disabled={loading}
            className="md:hidden flex items-center gap-2 px-6 py-3 bg-white text-slate-700 text-sm font-semibold rounded-xl border border-slate-200 hover:bg-slate-50 transition-all shadow-sm disabled:opacity-50"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
            </svg>
            Pridėti dar vieną
          </button>
        </div>
      </form>
    </div>
  )
}

import pool from '../config/database.js'

export async function createElectives(req, res, next) {
  try {
    const { entries } = req.body

    if (!entries || !Array.isArray(entries) || entries.length === 0) {
      return res.status(400).json({ error: 'Nėra duomenų išsaugojimui' })
    }

    // Filter valid entries (must have a name)
    const validEntries = entries.filter(e => e.name.trim().length > 0)
    
    if (validEntries.length === 0) {
      return res.status(400).json({ error: 'Nėra galiojančių duomenų išsaugojimui' })
    }

    // Validate name length
    for (const e of validEntries) {
      if (e.name.trim().length > 50) {
        return res.status(400).json({ error: `Pavadinimas per ilgas (maks. 50 simbolių): "${e.name.trim().substring(0, 20)}..."` })
      }
    }

    // Validate credits are required and positive
    for (const e of validEntries) {
      if (e.credits === '' || e.credits == null) {
        return res.status(400).json({ error: `Kreditai privalomi: "${e.name}"` })
      }
      const credits = parseInt(e.credits, 10)
      if (isNaN(credits) || credits <= 0) {
        return res.status(400).json({ error: `Kreditai turi būti teigiamas skaičius: "${e.name}"` })
      }
    }

    // Check for duplicates in DB (same name + credits for this user)
    for (const e of validEntries) {
      const credits = parseInt(e.credits, 10)
      const [existing] = await pool.query(
        'SELECT id FROM user_elective_courses WHERE user_id = ? AND LOWER(name) = LOWER(?) AND credits = ?',
        [req.user.id, e.name.trim(), credits]
      )
      if (existing.length > 0) {
        return res.status(409).json({ error: `Dalykas "${e.name}" su ${credits} kreditais jau yra išsaugotas` })
      }
    }

    // Prepare for bulk insert: [[user_id, name, credits, description], [...]]
    const values = validEntries.map(e => {
      const credits = parseInt(e.credits, 10)
      return [
        req.user.id,
        e.name.trim(),
        !isNaN(credits) && credits > 0 ? credits : null,
        e.description?.trim() || null
      ]
    })

    const query = 'INSERT INTO user_elective_courses (user_id, name, credits, description) VALUES ?'
    const [result] = await pool.query(query, [values])

    res.status(201).json({ 
      message: 'Dalykai sėkmingai išsaugoti',
      insertedCount: result.affectedRows
    })
  } catch (err) {
    next(err)
  }
}
